/**
 * Image credits for every fighter face, generated by the face pipeline into credits.json.
 * Each entry names the source file, author, licence and the edits made, and carries the face's average skin tone.
 * The credits screen lists them and the head model uses the tone so the photo blends into the rest of the head.
 */
import { UnknownEntityError } from '../core/errors';
import data from './credits.json';

export interface FaceCredit {
  id: string;
  file: string;
  sourceUrl: string;
  author: string;
  license: string;
  licenseUrl: string;
  changes: string;
  /** CSS hex colour such as "#c89a80". */
  tone: string;
}

export const FACE_CREDITS: readonly FaceCredit[] = data.credits;

const BY_ID = new Map(FACE_CREDITS.map((c) => [c.id, c]));

export function creditFor(fighterId: string): FaceCredit {
  const credit = BY_ID.get(fighterId);
  if (!credit) throw new UnknownEntityError(`No face credit for ${fighterId}`);
  return credit;
}

/** The face's skin tone as a 0xRRGGBB number. */
export function toneOf(fighterId: string): number {
  return Number.parseInt(creditFor(fighterId).tone.slice(1), 16);
}
